import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Get watermark high_ts (single row)
    high_ts = watermark["high_ts"].iloc[0]

    # Step 1: keep only events with event_ts > watermark.high_ts
    events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Step 2: per product_id, pick latest event by (event_ts, event_seq)
    if not events.empty:
        events = events.sort_values(
            by=["product_id", "event_ts", "event_seq"],
            ascending=[True, True, True],
        )
        latest_events = events.groupby("product_id", as_index=False).tail(1)
    else:
        latest_events = events.copy()

    # Build dict of current snapshot keyed by product_id
    snapshot = target_snapshot.set_index("product_id", drop=False).to_dict(orient="index")

    # Apply latest events
    for _, row in latest_events.iterrows():
        pid = row["product_id"]
        op = row["op"]
        if op == "D":
            if pid in snapshot:
                del snapshot[pid]
        elif op in ("I", "U"):
            snapshot[pid] = {
                "product_id": pid,
                "name": row["name"],
                "price": row["price"],
                "last_event_ts": row["event_ts"],
            }
        # unknown op values: ignore (no spec given)

    # Build output DataFrame preserving target_snapshot's column order/dtypes
    cols = list(target_snapshot.columns)
    if snapshot:
        new_snapshot = pd.DataFrame(list(snapshot.values()), columns=cols)
    else:
        new_snapshot = pd.DataFrame(columns=cols)

    # Try to restore original dtypes where possible
    for col in cols:
        try:
            new_snapshot[col] = new_snapshot[col].astype(target_snapshot[col].dtype)
        except (ValueError, TypeError):
            pass

    new_snapshot = new_snapshot.reset_index(drop=True)

    return {"new_snapshot": new_snapshot}
